import java.lang.Integer;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class HistoricalContractTest{@Test void handTracedSmallAndFullDomainBoundary(){List<List<Integer>>expected=List.of(List.of(2),List.of(2,1),List.of(2,4,3),List.of(2,4,6,3,1));int[]n={2,3,4,6},last={1,3,1,5};for(int j=0;j<n.length;j++)for(int k=0;k<2;k++){assertEquals(expected.get(j),TaskBinding.removed(n[j],k));assertEquals(last[j],TaskBinding.survivor(n[j],k));}int limit=10000;List<Integer>a=TaskBinding.removed(limit,0),b=TaskBinding.removed(limit,1);assertEquals(a,b);assertEquals(limit-1,a.size());Set<Integer>all=new HashSet<>(a);assertEquals(limit-1,all.size());assertFalse(all.contains(TaskBinding.survivor(limit,0)));all.add(TaskBinding.survivor(limit,0));assertEquals(limit,all.size());for(int i=1;i<=limit;i++)assertTrue(all.contains(i));assertEquals(TaskBinding.survivor(limit,0),TaskBinding.survivor(limit,1));}}
